import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"URI Protocol (lertaro://)","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/uri-protocol.md","filePath":"user-guide/uri-protocol.md","lastUpdated":1785993908000}'),s={name:"user-guide/uri-protocol.md"};function n(i,e,d,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="uri-protocol-lertaro" tabindex="-1">URI Protocol (lertaro://) <a class="header-anchor" href="#uri-protocol-lertaro" aria-label="Permalink to &quot;URI Protocol (lertaro://)&quot;">​</a></h1><p>Lertaro registers itself as the handler for a <code>lertaro://</code> link — no separate installer step, it&#39;s set up automatically the first time the app runs. This lets anything that can open a link (a browser, a shortcut, another app, a script) jump straight into a specific part of Lertaro, instead of only being reachable through a hotkey.</p><p>If Lertaro isn&#39;t already running, opening a <code>lertaro://</code> link starts it and then follows the link. If it&#39;s already running, the running instance handles the link directly — it never starts a second copy.</p><h2 id="routes" tabindex="-1">Routes <a class="header-anchor" href="#routes" aria-label="Permalink to &quot;Routes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Link</th><th>What it does</th></tr></thead><tbody><tr><td><code>lertaro://</code></td><td>Activates the quick search window — same as summoning it with its hotkey.</td></tr><tr><td><code>lertaro://search/[keyword]</code></td><td>Activates the quick search window with <code>[keyword]</code> pre-filled.</td></tr><tr><td><code>lertaro://fullsearch/[keyword]</code></td><td>Opens the full search window with <code>[keyword]</code> pre-filled.</td></tr><tr><td><code>lertaro://settings/page/[section]</code></td><td>Opens Settings to a specific top-level section.</td></tr><tr><td><code>lertaro://settings/entry/[index]</code></td><td>Opens Settings and jumps straight to one specific setting, highlighted.</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://search/report</span></span>
<span class="line"><span>lertaro://settings/page/Appearance</span></span></code></pre></div><p>The first activates the quick search window already filtered to &quot;report&quot;; the second opens Settings directly on the Appearance page.</p><p><code>[section]</code> matches one of the top-level sidebar entries: <code>Service</code>, <code>Index</code>, <code>General</code>, <code>Appearance</code>, <code>Hotkeys</code>, <code>Plugins</code>, <code>Favorites</code>, <code>History</code>, <code>QuickPanel</code>, <code>About</code> — not case-sensitive.</p><p><code>[index]</code> isn&#39;t meant to be typed by hand — it&#39;s a number <a href="./instant-answers.html">Settings Search</a> generates itself for whatever setting you picked, so selecting one of its results round-trips straight back to that exact row. It isn&#39;t stable across restarts, so don&#39;t rely on a specific number staying the same.</p><h2 id="unrecognized-links" tabindex="-1">Unrecognized links <a class="header-anchor" href="#unrecognized-links" aria-label="Permalink to &quot;Unrecognized links&quot;">​</a></h2><p>Anything that doesn&#39;t match a known route — a typo, an unsupported section, garbage after <code>lertaro://</code> — is silently ignored. Since any website or app can invoke this protocol without asking you first, a bad or unexpected link should never do anything surprising; it&#39;s logged for your own troubleshooting, but nothing else happens.</p>`,11)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
